-- ============================================================================
--  Qatar Travel Map — schema
--
--  Target: MariaDB 10.4+ / MySQL 5.7+  (XAMPP 8.2.x ships MariaDB 10.4)
--  Charset: utf8mb4 everywhere — Arabic needs it, and so does any Bengali later.
--
--  Scope note: this schema covers the whole roadmap from features.md, not just
--  the first release. Tables for itineraries, badges, admin and analytics exist
--  from day one so that adding those features later is a UI job, not a migration.
--
--  Import order:  schema.sql  ->  seed.sql
--  seed.sql is generated by setup/prepare.php. Do not hand-edit it.
-- ============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;

CREATE DATABASE IF NOT EXISTS `explore_qatar`
    DEFAULT CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;
USE `explore_qatar`;

-- Drop in dependency order so the script is re-runnable.
DROP TABLE IF EXISTS activity_log, admin_login_attempts, feedback, card_events,
    saved_map_items, saved_maps, itinerary_stops, itineraries, collection_places,
    collections, place_tag, tags, place_images, places, categories, localities,
    municipalities, guide_pages, share_themes, personalities, badges, levels,
    settings, admin_users, translations;


-- ============================================================================
--  1. Geography
-- ============================================================================

CREATE TABLE municipalities (
    id          TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    code        CHAR(4)      NOT NULL COMMENT 'SVG path id — QADA, QAKH, …',
    slug        VARCHAR(32)  NOT NULL,
    name_en     VARCHAR(64)  NOT NULL,
    name_ar     VARCHAR(64)  NOT NULL,
    alt_en      VARCHAR(64)  NOT NULL DEFAULT '' COMMENT 'Alternate English spelling',
    blurb_en    VARCHAR(255) NOT NULL DEFAULT '',
    blurb_ar    VARCHAR(255) NOT NULL DEFAULT '',
    sort_order  SMALLINT     NOT NULL DEFAULT 0,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_mun_code (code),
    UNIQUE KEY uq_mun_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE localities (
    id              SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    municipality_id TINYINT UNSIGNED  NOT NULL,
    slug            VARCHAR(64)  NOT NULL,
    name_en         VARCHAR(96)  NOT NULL,
    name_ar         VARCHAR(96)  NOT NULL,
    lat             DECIMAL(9,6) NOT NULL,
    lng             DECIMAL(9,6) NOT NULL,
    kind            ENUM('city','town','district','landmark','industrial','natural')
                                 NOT NULL DEFAULT 'town',
    is_featured     TINYINT(1)   NOT NULL DEFAULT 0,
    sort_order      SMALLINT     NOT NULL DEFAULT 0,
    created_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_loc_slug (slug),
    KEY idx_loc_mun (municipality_id),
    KEY idx_loc_kind (kind),
    CONSTRAINT fk_loc_mun FOREIGN KEY (municipality_id)
        REFERENCES municipalities (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ============================================================================
--  2. Content — places and their taxonomy
-- ============================================================================

CREATE TABLE categories (
    id          TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug        VARCHAR(32)  NOT NULL,
    name_en     VARCHAR(64)  NOT NULL,
    name_ar     VARCHAR(64)  NOT NULL,
    icon        VARCHAR(32)  NOT NULL DEFAULT '',
    color       CHAR(7)      NOT NULL DEFAULT '#6f9c76',
    sort_order  SMALLINT     NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_cat_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE tags (
    id          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug        VARCHAR(48) NOT NULL,
    name_en     VARCHAR(64) NOT NULL,
    name_ar     VARCHAR(64) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_tag_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE places (
    id              SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    municipality_id TINYINT UNSIGNED  NOT NULL,
    locality_id     SMALLINT UNSIGNED NULL,
    category_id     TINYINT UNSIGNED  NULL,
    slug            VARCHAR(96)  NOT NULL,
    name_en         VARCHAR(128) NOT NULL,
    name_ar         VARCHAR(128) NOT NULL,
    summary_en      VARCHAR(500) NOT NULL DEFAULT '',
    summary_ar      VARCHAR(500) NOT NULL DEFAULT '',
    description_en  TEXT NULL,
    description_ar  TEXT NULL,
    tips_en         TEXT NULL COMMENT 'The "things visitors get wrong" notes',
    tips_ar         TEXT NULL,
    lat             DECIMAL(9,6) NOT NULL,
    lng             DECIMAL(9,6) NOT NULL,
    -- Practical info. Ranges rather than single values, because "QAR 0-50" is honest
    -- and a fake precise number is not.
    fee_level       ENUM('free','low','medium','high') NOT NULL DEFAULT 'free',
    fee_note_en     VARCHAR(160) NOT NULL DEFAULT '',
    fee_note_ar     VARCHAR(160) NOT NULL DEFAULT '',
    duration_mins   SMALLINT UNSIGNED NULL COMMENT 'Typical time spent, minutes',
    best_time_en    VARCHAR(160) NOT NULL DEFAULT '',
    best_time_ar    VARCHAR(160) NOT NULL DEFAULT '',
    -- Filtering facets from features.md
    is_hidden_gem   TINYINT(1) NOT NULL DEFAULT 0,
    is_featured     TINYINT(1) NOT NULL DEFAULT 0,
    family_friendly TINYINT(1) NOT NULL DEFAULT 1,
    metro_access    TINYINT(1) NOT NULL DEFAULT 0,
    indoor          TINYINT(1) NOT NULL DEFAULT 0,
    season          ENUM('all','winter','summer') NOT NULL DEFAULT 'all',
    map_url         VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'Google Maps link',
    official_url    VARCHAR(255) NOT NULL DEFAULT '',
    -- Editorial workflow
    status          ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',
    source_note     VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'Where the facts came from',
    verified_at     DATE NULL COMMENT 'Last time a human checked the details',
    views           INT UNSIGNED NOT NULL DEFAULT 0,
    visit_marks     INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'How many people ticked this',
    sort_order      SMALLINT NOT NULL DEFAULT 0,
    deleted_at      TIMESTAMP NULL DEFAULT NULL,
    created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_place_slug (slug),
    KEY idx_place_mun (municipality_id),
    KEY idx_place_loc (locality_id),
    KEY idx_place_cat (category_id),
    KEY idx_place_status (status, deleted_at),
    KEY idx_place_flags (is_hidden_gem, is_featured),
    KEY idx_place_fee (fee_level),
    FULLTEXT KEY ft_place (name_en, name_ar, summary_en, description_en),
    CONSTRAINT fk_place_mun FOREIGN KEY (municipality_id)
        REFERENCES municipalities (id) ON DELETE CASCADE,
    CONSTRAINT fk_place_loc FOREIGN KEY (locality_id)
        REFERENCES localities (id) ON DELETE SET NULL,
    CONSTRAINT fk_place_cat FOREIGN KEY (category_id)
        REFERENCES categories (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE place_tag (
    place_id    SMALLINT UNSIGNED NOT NULL,
    tag_id      SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (place_id, tag_id),
    KEY idx_pt_tag (tag_id),
    CONSTRAINT fk_pt_place FOREIGN KEY (place_id) REFERENCES places (id) ON DELETE CASCADE,
    CONSTRAINT fk_pt_tag   FOREIGN KEY (tag_id)   REFERENCES tags (id)   ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE place_images (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    place_id    SMALLINT UNSIGNED NOT NULL,
    path        VARCHAR(255) NOT NULL COMMENT 'Relative to /uploads',
    thumb_path  VARCHAR(255) NOT NULL DEFAULT '',
    webp_path   VARCHAR(255) NOT NULL DEFAULT '',
    caption_en  VARCHAR(255) NOT NULL DEFAULT '',
    caption_ar  VARCHAR(255) NOT NULL DEFAULT '',
    credit      VARCHAR(160) NOT NULL DEFAULT '' COMMENT 'Photographer',
    licence     VARCHAR(80)  NOT NULL DEFAULT '' COMMENT 'e.g. CC BY-SA 4.0, own work',
    is_cover    TINYINT(1)   NOT NULL DEFAULT 0,
    sort_order  SMALLINT     NOT NULL DEFAULT 0,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_img_place (place_id, sort_order),
    CONSTRAINT fk_img_place FOREIGN KEY (place_id) REFERENCES places (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ============================================================================
--  3. Gamification — badges, levels, personality cards, share themes
-- ============================================================================

CREATE TABLE levels (
    id          TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug        VARCHAR(32) NOT NULL,
    name_en     VARCHAR(64) NOT NULL,
    name_ar     VARCHAR(64) NOT NULL,
    min_places  SMALLINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Places needed to reach this level',
    color       CHAR(7) NOT NULL DEFAULT '#6f9c76',
    sort_order  SMALLINT NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_level_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE badges (
    id            SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug          VARCHAR(48) NOT NULL,
    name_en       VARCHAR(64) NOT NULL,
    name_ar       VARCHAR(64) NOT NULL,
    description_en VARCHAR(255) NOT NULL DEFAULT '',
    description_ar VARCHAR(255) NOT NULL DEFAULT '',
    icon          VARCHAR(32) NOT NULL DEFAULT '',
    -- Rule is stored as JSON so a badge can be added without a code change.
    -- {"type":"municipalities_all"} | {"type":"count","n":10}
    -- {"type":"kind","kind":"natural","n":3} | {"type":"category","slug":"beach","n":5}
    rule_json     JSON NOT NULL,
    is_active     TINYINT(1) NOT NULL DEFAULT 1,
    sort_order    SMALLINT NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_badge_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE personalities (
    id            TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug          VARCHAR(32) NOT NULL,
    name_en       VARCHAR(64) NOT NULL COMMENT 'e.g. "Desert Soul"',
    name_ar       VARCHAR(64) NOT NULL,
    blurb_en      VARCHAR(255) NOT NULL DEFAULT '',
    blurb_ar      VARCHAR(255) NOT NULL DEFAULT '',
    -- Scores each personality against what the user marked, e.g.
    -- {"natural":3,"desert":2,"beach":-1} — highest total wins.
    weights_json  JSON NOT NULL,
    priority      SMALLINT NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_pers_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE share_themes (
    id          TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug        VARCHAR(32) NOT NULL COMMENT 'maroon, desert, night, …',
    name_en     VARCHAR(64) NOT NULL,
    name_ar     VARCHAR(64) NOT NULL,
    -- Colours used by both the live map and the canvas renderer, so the
    -- downloaded card always matches what was on screen.
    bg          CHAR(7) NOT NULL DEFAULT '#ffffff',
    land        CHAR(7) NOT NULL DEFAULT '#e2e8f0' COMMENT 'Unvisited municipality',
    visited     CHAR(7) NOT NULL DEFAULT '#6f9c76' COMMENT 'Visited municipality',
    accent      CHAR(7) NOT NULL DEFAULT '#0f1720',
    ink         CHAR(7) NOT NULL DEFAULT '#0f1720',
    ink_soft    CHAR(7) NOT NULL DEFAULT '#64748b',
    is_dark     TINYINT(1) NOT NULL DEFAULT 0,
    sort_order  SMALLINT NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_theme_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ============================================================================
--  4. Planning — itineraries and collections
-- ============================================================================

CREATE TABLE itineraries (
    id           SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug         VARCHAR(96) NOT NULL,
    title_en     VARCHAR(160) NOT NULL,
    title_ar     VARCHAR(160) NOT NULL,
    intro_en     TEXT NULL,
    intro_ar     TEXT NULL,
    -- Trip shape
    duration_type ENUM('hours','days') NOT NULL DEFAULT 'days',
    duration_value TINYINT UNSIGNED NOT NULL DEFAULT 1,
    audience     ENUM('family','couple','budget','adventure','solo','any')
                              NOT NULL DEFAULT 'any',
    budget_level ENUM('free','low','medium','high') NOT NULL DEFAULT 'medium',
    cover_image  VARCHAR(255) NOT NULL DEFAULT '',
    status       ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',
    verified_at  DATE NULL,
    sort_order   SMALLINT NOT NULL DEFAULT 0,
    deleted_at   TIMESTAMP NULL DEFAULT NULL,
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_itin_slug (slug),
    KEY idx_itin_shape (duration_type, duration_value, audience),
    KEY idx_itin_status (status, deleted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE itinerary_stops (
    id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    itinerary_id  SMALLINT UNSIGNED NOT NULL,
    place_id      SMALLINT UNSIGNED NULL COMMENT 'NULL = free-text stop, not a listed place',
    day_number    TINYINT UNSIGNED NOT NULL DEFAULT 1,
    sort_order    SMALLINT NOT NULL DEFAULT 0,
    time_note_en  VARCHAR(120) NOT NULL DEFAULT '' COMMENT 'e.g. "arrive before 4pm"',
    time_note_ar  VARCHAR(120) NOT NULL DEFAULT '',
    note_en       VARCHAR(255) NOT NULL DEFAULT '',
    note_ar       VARCHAR(255) NOT NULL DEFAULT '',
    PRIMARY KEY (id),
    KEY idx_stop_itin (itinerary_id, day_number, sort_order),
    CONSTRAINT fk_stop_itin  FOREIGN KEY (itinerary_id) REFERENCES itineraries (id) ON DELETE CASCADE,
    CONSTRAINT fk_stop_place FOREIGN KEY (place_id)     REFERENCES places (id)      ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE collections (
    id          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug        VARCHAR(64) NOT NULL,
    title_en    VARCHAR(160) NOT NULL,
    title_ar    VARCHAR(160) NOT NULL,
    blurb_en    VARCHAR(255) NOT NULL DEFAULT '',
    blurb_ar    VARCHAR(255) NOT NULL DEFAULT '',
    kind        ENUM('hidden_gems','seasonal','featured','editorial') NOT NULL DEFAULT 'editorial',
    status      ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',
    sort_order  SMALLINT NOT NULL DEFAULT 0,
    deleted_at  TIMESTAMP NULL DEFAULT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_col_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE collection_places (
    collection_id SMALLINT UNSIGNED NOT NULL,
    place_id      SMALLINT UNSIGNED NOT NULL,
    sort_order    SMALLINT NOT NULL DEFAULT 0,
    PRIMARY KEY (collection_id, place_id),
    CONSTRAINT fk_cp_col   FOREIGN KEY (collection_id) REFERENCES collections (id) ON DELETE CASCADE,
    CONSTRAINT fk_cp_place FOREIGN KEY (place_id)      REFERENCES places (id)      ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ============================================================================
--  5. Shared maps — the viral loop
-- ============================================================================

CREATE TABLE saved_maps (
    id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    code          CHAR(7)      NOT NULL COMMENT 'Short public id, base62',
    display_name  VARCHAR(48)  NULL COMMENT 'What the user typed. Escaped on output.',
    theme         VARCHAR(32)  NOT NULL DEFAULT 'maroon',
    personality   VARCHAR(32)  NULL COMMENT 'personalities.slug, computed client-side',
    level_slug    VARCHAR(32)  NULL COMMENT 'levels.slug at time of saving',
    -- The rendered card. Doubles as og:image, so shares on Facebook show the map
    -- itself rather than a generic logo — this is what drives the viral loop.
    snapshot      MEDIUMBLOB   NULL,
    shot_w        SMALLINT UNSIGNED NULL,
    shot_h        SMALLINT UNSIGNED NULL,
    shot_bytes    INT UNSIGNED NULL,
    mun_count     TINYINT UNSIGNED NOT NULL DEFAULT 0,
    loc_count     TINYINT UNSIGNED NOT NULL DEFAULT 0,
    lang          CHAR(2)      NOT NULL DEFAULT 'en',
    ip_hash       CHAR(64)     NULL COMMENT 'HMAC of IP — for rate limiting, never the raw IP',
    views         INT UNSIGNED NOT NULL DEFAULT 0,
    status        ENUM('active','hidden','deleted') NOT NULL DEFAULT 'active',
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_map_code (code),
    KEY idx_map_created (created_at),
    KEY idx_map_rate (ip_hash, created_at),
    KEY idx_map_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Normalised rather than a JSON blob on saved_maps, so "which places do people
-- mark most" is a GROUP BY instead of a JSON scan.
CREATE TABLE saved_map_items (
    saved_map_id INT UNSIGNED NOT NULL,
    item_type    ENUM('municipality','locality') NOT NULL,
    item_id      SMALLINT UNSIGNED NOT NULL COMMENT 'municipalities.id or localities.id',
    PRIMARY KEY (saved_map_id, item_type, item_id),
    KEY idx_smi_item (item_type, item_id),
    CONSTRAINT fk_smi_map FOREIGN KEY (saved_map_id) REFERENCES saved_maps (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE card_events (
    id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
    saved_map_id INT UNSIGNED NULL,
    event        ENUM('create','view','download','share','share_click') NOT NULL,
    format       VARCHAR(16) NOT NULL DEFAULT '' COMMENT 'png_1x1, png_9x16, pdf, …',
    theme        VARCHAR(32) NOT NULL DEFAULT '',
    referrer     VARCHAR(255) NOT NULL DEFAULT '',
    ip_hash      CHAR(64) NULL,
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_ev_map (saved_map_id),
    KEY idx_ev_kind (event, created_at),
    CONSTRAINT fk_ev_map FOREIGN KEY (saved_map_id) REFERENCES saved_maps (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ============================================================================
--  6. Visitor guide
-- ============================================================================

CREATE TABLE guide_pages (
    id          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug        VARCHAR(64) NOT NULL,
    title_en    VARCHAR(160) NOT NULL,
    title_ar    VARCHAR(160) NOT NULL,
    body_en     MEDIUMTEXT NULL,
    body_ar     MEDIUMTEXT NULL,
    section     ENUM('visa','transport','customs','practical','mistakes') NOT NULL DEFAULT 'practical',
    sort_order  SMALLINT NOT NULL DEFAULT 0,
    status      ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',
    -- Every guide page must cite a government/operator source and a check date.
    source_url  VARCHAR(255) NOT NULL DEFAULT '',
    source_note VARCHAR(160) NOT NULL DEFAULT '',
    verified_at DATE NULL,
    deleted_at  TIMESTAMP NULL DEFAULT NULL,
    updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_guide_slug (slug),
    KEY idx_guide_section (section, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ============================================================================
--  7. Admin, i18n, feedback, settings
-- ============================================================================

CREATE TABLE admin_users (
    id            SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    email         VARCHAR(160) NOT NULL,
    name          VARCHAR(96)  NOT NULL DEFAULT '',
    password_hash VARCHAR(255) NOT NULL,
    role          ENUM('admin','editor') NOT NULL DEFAULT 'editor',
    totp_secret   VARCHAR(64) NULL COMMENT 'Optional 2FA',
    is_active     TINYINT(1) NOT NULL DEFAULT 1,
    last_login_at TIMESTAMP NULL DEFAULT NULL,
    created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_admin_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Every sign-in attempt, successful or not. Two jobs: it is the audit trail the
-- Security screen shows, and it is what the throttle counts. Kept separate from
-- activity_log because a failed attempt has no admin_id to point at — only the
-- email someone tried.
CREATE TABLE admin_login_attempts (
    id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    email      VARCHAR(160) NOT NULL DEFAULT '',
    ip_hash    CHAR(64)     NOT NULL DEFAULT '',
    ok         TINYINT(1)   NOT NULL DEFAULT 0,
    reason     VARCHAR(32)  NOT NULL DEFAULT '' COMMENT 'bad_password, unknown_email, locked, 2fa',
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_la_email (email, created_at),
    KEY idx_la_ip (ip_hash, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Extra languages beyond the two launch ones (English and Arabic live in the
-- _en/_ar columns so the common case needs no join). Add Hindi/Urdu/Bengali here
-- when features.md's later phases arrive.
CREATE TABLE translations (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    entity_type ENUM('place','locality','municipality','category','tag',
                     'itinerary','guide_page','collection','ui') NOT NULL,
    entity_id   INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 = UI string',
    field       VARCHAR(48) NOT NULL,
    lang        CHAR(5) NOT NULL COMMENT 'BCP-47-ish: hi, ur, bn',
    value       TEXT NOT NULL,
    updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_tr (entity_type, entity_id, field, lang),
    KEY idx_tr_lang (lang)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE feedback (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    kind        ENUM('wrong_info','new_place','bug','other') NOT NULL DEFAULT 'other',
    entity_type VARCHAR(32) NOT NULL DEFAULT '',
    entity_id   INT UNSIGNED NULL,
    message     TEXT NOT NULL,
    contact     VARCHAR(160) NOT NULL DEFAULT '',
    status      ENUM('new','in_review','done','rejected') NOT NULL DEFAULT 'new',
    admin_note  TEXT NULL,
    ip_hash     CHAR(64) NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_fb_status (status, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE activity_log (
    id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    admin_id    SMALLINT UNSIGNED NULL,
    module      VARCHAR(32) NOT NULL,
    action      VARCHAR(32) NOT NULL,
    entity_type VARCHAR(32) NOT NULL DEFAULT '',
    entity_id   INT UNSIGNED NULL,
    before_json JSON NULL COMMENT 'Previous values, for undo and for "who broke this"',
    after_json  JSON NULL,
    ip_hash     CHAR(64) NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_log_admin (admin_id, created_at),
    KEY idx_log_module (module, created_at),
    CONSTRAINT fk_log_admin FOREIGN KEY (admin_id) REFERENCES admin_users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE settings (
    k           VARCHAR(64) NOT NULL,
    v           TEXT NULL,
    updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (k)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ============================================================================
--  8. Views for the admin dashboard
-- ============================================================================

CREATE OR REPLACE VIEW v_stale_places AS
SELECT p.id, p.slug, p.name_en, m.name_en AS municipality, p.verified_at,
       DATEDIFF(CURDATE(), COALESCE(p.verified_at, '1970-01-01')) AS days_since_check
FROM places p
JOIN municipalities m ON m.id = p.municipality_id
WHERE p.deleted_at IS NULL
  AND p.status = 'published'
  AND (p.verified_at IS NULL OR p.verified_at < CURDATE() - INTERVAL 90 DAY)
ORDER BY days_since_check DESC;

CREATE OR REPLACE VIEW v_missing_images AS
SELECT p.id, p.slug, p.name_en, m.name_en AS municipality
FROM places p
JOIN municipalities m ON m.id = p.municipality_id
LEFT JOIN place_images i ON i.place_id = p.id
WHERE p.deleted_at IS NULL AND i.id IS NULL
ORDER BY p.name_en;

CREATE OR REPLACE VIEW v_popular_localities AS
SELECT smi.item_id AS locality_id, l.name_en, l.slug, COUNT(*) AS marks
FROM saved_map_items smi
JOIN localities l ON l.id = smi.item_id
WHERE smi.item_type = 'locality'
GROUP BY smi.item_id, l.name_en, l.slug
ORDER BY marks DESC;
